<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import CharacterIcon from '@/components/icons/CharacterIcon.vue'
import { loadValue, saveValue } from '@/stores/db'

const emit = defineEmits(['close'])
const characters = ref([])
const builderStep = ref(0)
const view = ref('desk')
const posterCharacter = ref(null)
const editDraft = ref(null)
const selectedForTrash = ref(null)
const builderDraft = ref(null)
const expandedDetails = ref(false)
const builderClues = [
  { key: 'name', title: '角色叫什么？', hint: '', label: '名字', placeholder: '输入角色名字' },
  { key: 'occupation', title: '他是谁？', hint: '', label: '身份', placeholder: '例如：夜班护士、流浪画家' },
  { key: 'gender', title: '如何称呼他？', hint: '', label: '称呼', placeholder: '自由填写' },
  { key: 'age', title: '他多大？', hint: '', label: '年龄', placeholder: '例如：二十多岁' },
  { key: 'birthday', title: '生日', hint: '', label: '生日', placeholder: '' },
  { key: 'details', title: '还有什么故事？', hint: '', label: '设定', placeholder: '性格、外貌、经历……' }
]
const activeBuilderClue = computed(() => builderClues[builderStep.value] || builderClues[0])
const builderCompletedCount = computed(() => builderClues.filter((clue) => String(builderDraft.value?.[clue.key] || '').trim()).length)
let nextId = 1

onMounted(async () => {
  const draft = createDraft()
  builderDraft.value = draft
  try {
    const saved = await loadValue('jyos_characters')
    if (Array.isArray(saved)) {
      characters.value = saved
      nextId = Math.max(0, ...saved.map((character) => Number(character.id) || 0)) + 1
      if (draft.id < nextId) draft.id = nextId++
    }
    const restored = await loadValue('jyos_character_builder_draft')
    if (restored && Number.isInteger(restored.id) && !characters.value.some((character) => character.id === restored.id)) {
      Object.assign(draft, restored)
      nextId = Math.max(nextId, restored.id + 1)
    }
  } catch (error) {
    console.error('加载角色数据失败', error)
  }
})
watch(characters, (value) => saveValue('jyos_characters', JSON.parse(JSON.stringify(value))), { deep: true })
watch(builderDraft, (value) => {
  if (value) void saveValue('jyos_character_builder_draft', JSON.parse(JSON.stringify(value)))
}, { deep: true })

function createDraft() {
  return { id: nextId++, name: '', details: '', birthday: '', age: '', occupation: '', gender: '', avatar: '', favorite: false, color: '#f1f1f1' }
}

function createCharacter() {
  const character = builderDraft.value
  if (!character?.name.trim()) return false
  const savedCharacter = JSON.parse(JSON.stringify(character))
  characters.value.push(savedCharacter)
  posterCharacter.value = savedCharacter
  builderDraft.value = createDraft()
  return true
}

function openBuilder() {
  view.value = 'builder'
}

function openPoster(character) {
  posterCharacter.value = character
  editDraft.value = JSON.parse(JSON.stringify(character))
  view.value = 'poster'
}

function savePosterEdits() {
  if (!editDraft.value || !posterCharacter.value) return
  Object.assign(posterCharacter.value, JSON.parse(JSON.stringify(editDraft.value)))
  view.value = 'files'
}

function returnToDesk() {
  view.value = 'desk'
}

function toggleTrashSelection(character) {
  selectedForTrash.value = selectedForTrash.value === character.id ? null : character.id
}

function discardSelectedCharacter() {
  if (selectedForTrash.value === null) return
  characters.value = characters.value.filter((character) => character.id !== selectedForTrash.value)
  if (posterCharacter.value?.id === selectedForTrash.value) posterCharacter.value = null
  selectedForTrash.value = null
}

function openClue(index) {
  if (!builderDraft.value) return
  builderStep.value = index
}

function finishBuilder() {
  if (createCharacter()) view.value = 'poster'
  builderStep.value = 0
}

function closeBuilder() {
  emit('close')
}

function selectDraftAvatar(event) {
  const file = event.target.files?.[0]
  event.target.value = ''
  if (!file || !file.type.startsWith('image/')) return
  const reader = new FileReader()
  reader.onload = () => {
    const image = new Image()
    image.onload = () => {
      const scale = Math.min(1, 800 / Math.max(image.width, image.height))
      const canvas = document.createElement('canvas')
      canvas.width = Math.round(image.width * scale)
      canvas.height = Math.round(image.height * scale)
      canvas.getContext('2d').drawImage(image, 0, 0, canvas.width, canvas.height)
      if (editDraft.value) editDraft.value.avatar = canvas.toDataURL('image/jpeg', 0.85)
      else if (builderDraft.value) builderDraft.value.avatar = canvas.toDataURL('image/jpeg', 0.85)
    }
    image.src = reader.result
  }
  reader.readAsDataURL(file)
}
</script>

<template>
  <div class="character-app">
    <section v-if="view === 'desk'" class="studio-scene" aria-label="角色工作台">
      <header class="studio-header"><button type="button" @click="emit('close')">←</button><h1>角色工作台</h1><span>{{ characters.length }} 张档案</span></header>
      <div class="studio-table">
        <div class="desk-lamp"><i/><b/></div><div class="desk-cup"><i/><i/><i/></div>
        <button class="desk-tool file-stack" type="button" aria-label="打开角色档案" @click="view = 'files'"><span class="file-sheet sheet-back"/><span class="file-sheet sheet-front"><b>角色档案</b><i>{{ characters.length }} 张</i></span></button>
        <button class="desk-tool sketchbook" type="button" aria-label="开始构建角色" @click="openBuilder"><span class="sketch-cover"><CharacterIcon/><b>新建角色</b></span></button>
        <div class="desk-ruler"><i v-for="n in 9" :key="n"/></div>
        <button class="desk-trash" :class="{ 'trash-ready': selectedForTrash !== null }" type="button" :aria-label="selectedForTrash !== null ? '确认删除选中的角色' : '垃圾桶'" @click="selectedForTrash !== null ? discardSelectedCharacter() : view = 'files'"><span/><i/><b>{{ selectedForTrash !== null ? '确认删除' : '垃圾桶' }}</b></button>
      </div>
      <p class="desk-hint">点击档案查看角色，拖选后点击垃圾桶删除</p>
    </section>
    <section v-else-if="view === 'files'" class="files-view">
      <header class="studio-header"><button type="button" @click="returnToDesk">←</button><h1>角色档案</h1><button type="button" class="file-add" @click="openBuilder">＋ 新建</button></header>
      <div v-if="characters.length" class="poster-grid"><article v-for="character in characters" :key="character.id" class="poster-file" :class="{ selected: selectedForTrash === character.id }" @click="selectedForTrash === character.id ? openPoster(character) : openPoster(character)" @contextmenu.prevent="toggleTrashSelection(character)"><button class="poster-select" type="button" :aria-label="selectedForTrash === character.id ? '取消选择' : '选择删除'" @click.stop="toggleTrashSelection(character)">{{ selectedForTrash === character.id ? '✓' : '⋯' }}</button><div class="character-poster"><img v-if="character.avatar" :src="character.avatar" :alt="`${character.name}形象`"/><CharacterIcon v-else/><span>{{ character.occupation || '角色档案' }}</span><h2>{{ character.name }}</h2><small>{{ [character.gender, character.age].filter(Boolean).join(' · ') }}</small></div></article></div>
      <div v-else class="files-empty"><button type="button" @click="openBuilder">开始构建角色</button></div>
      <footer v-if="selectedForTrash !== null" class="trash-confirm"><span>已选中一张角色档案</span><button type="button" @click="discardSelectedCharacter">移入垃圾桶</button><button type="button" @click="selectedForTrash = null">取消</button></footer>
    </section>
    <section v-else-if="view === 'poster' && posterCharacter" class="poster-detail">
      <header class="studio-header"><button type="button" @click="view = 'files'">← 档案</button><h1>{{ editDraft?.name || '角色档案' }}</h1><button type="button" class="file-add" @click="savePosterEdits">完成</button></header>
      <div v-if="editDraft" class="folder-open">
        <div class="folder-cover"><span>角色档案</span><i></i></div>
        <div class="folder-pocket"><div class="folder-tab">{{ editDraft.name || '新角色' }}</div>
          <div class="folder-document">
            <div class="folder-portrait"><img v-if="editDraft.avatar" :src="editDraft.avatar" :alt="`${editDraft.name}形象`"/><CharacterIcon v-else/><label class="folder-avatar-change"><input type="file" accept="image/*" @change="selectDraftAvatar"/><span>更换图片</span></label></div>
            <div class="folder-fields">
              <label class="folder-field"><span>名字</span><input v-model="editDraft.name" maxlength="80" placeholder="角色名字"/></label>
              <label class="folder-field"><span>身份</span><input v-model="editDraft.occupation" maxlength="80" placeholder="角色身份"/></label>
              <div class="folder-row"><label class="folder-field"><span>称呼</span><input v-model="editDraft.gender" maxlength="40" placeholder="称呼"/></label><label class="folder-field"><span>年龄</span><input v-model="editDraft.age" maxlength="40" placeholder="年龄"/></label></div>
              <label class="folder-field"><span>生日</span><input v-model="editDraft.birthday" type="date"/></label>
              <label class="folder-field"><span>设定</span><textarea v-model="editDraft.details" rows="7" placeholder="性格、外貌、经历……"/></label>
            </div>
          </div>
        </div>
      </div>
    </section>
    <transition name="builder-enter">
      <section v-if="view === 'builder' && builderDraft" class="builder-workspace" aria-label="角色身份名片编辑">
        <header class="builder-header"><button type="button" class="builder-back" aria-label="返回工作台" @click="view = 'desk'">←</button><span>NEW CHARACTER PROFILE</span><button type="button" class="builder-finish" @click="finishBuilder">保存角色</button></header>
        <div class="identity-editor">
          <section class="identity-card">
            <div class="identity-card-top"><span>IDENTITY CARD</span><span>NO. {{ String(builderDraft.id).padStart(4, '0') }}</span></div>
            <div class="identity-portrait"><img v-if="builderDraft.avatar" :src="builderDraft.avatar" alt="角色形象预览"/><CharacterIcon v-else/><label class="identity-avatar-change"><input type="file" accept="image/*" @change="selectDraftAvatar"/><span>{{ builderDraft.avatar ? '更换照片' : '添加照片' }}</span></label></div>
            <div class="identity-card-caption"><span>{{ builderDraft.occupation || 'CHARACTER PROFILE' }}</span><strong>{{ builderDraft.name || '角色姓名' }}</strong><small>{{ [builderDraft.gender, builderDraft.age].filter(Boolean).join(' · ') || '称呼 · 年龄' }}</small></div>
            <div class="identity-card-bottom"><span>PERSONAL ARCHIVE</span></div>
          </section>
          <section class="identity-fields">
            <div class="identity-heading"><span>PROFILE INFORMATION</span><h1>新建角色</h1><p>填写你想设定的内容，其他信息可以留空。</p></div>
            <div class="identity-form">
              <label class="identity-field identity-field-name"><span>姓名 <i>NAME</i></span><input v-model="builderDraft.name" maxlength="80" placeholder="角色名字" autofocus/></label>
              <label class="identity-field"><span>身份 <i>OCCUPATION</i></span><input v-model="builderDraft.occupation" maxlength="80" placeholder="例如：夜班护士、流浪画家"/></label>
              <div class="identity-field-row"><label class="identity-field"><span>称呼 <i>PRONOUN / GENDER</i></span><input v-model="builderDraft.gender" maxlength="40" placeholder="自由填写"/></label><label class="identity-field"><span>年龄 <i>AGE</i></span><input v-model="builderDraft.age" maxlength="40" placeholder="例如：二十多岁"/></label></div>
              <label class="identity-field"><span>生日 <i>BIRTHDAY</i></span><input v-model="builderDraft.birthday" type="date"/></label>
              <label class="identity-field identity-field-details"><span>角色设定 <i>PERSONALITY · STORY · DETAILS</i></span><textarea v-model="builderDraft.details" rows="7" placeholder="性格、外貌、经历、说话方式，以及你希望保留的其他设定……"/></label>
            </div>
            <footer class="identity-actions"><span>{{ builderDraft.name.trim() ? '名片会自动保存为角色档案' : '姓名为必填，其余信息可稍后补充' }}</span><button type="button" :disabled="!builderDraft.name.trim()" @click="finishBuilder">保存角色 <b>→</b></button></footer>
          </section>
        </div>
      </section>
    </transition>
    <div v-if="expandedDetails && view === 'builder'" class="details-modal" @click.self="expandedDetails = false" @keydown.esc="expandedDetails = false">
      <section class="details-modal-card" role="dialog" aria-modal="true" aria-labelledby="details-modal-title">
        <header><h2 id="details-modal-title">还有什么故事？</h2><button type="button" aria-label="关闭大视图编辑" @click="expandedDetails = false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header>
        <textarea v-model="builderDraft.details" autofocus placeholder="写下角色的性格、外貌、经历和故事……" />
        <footer><button type="button" @click="expandedDetails = false">完成</button></footer>
      </section>
    </div>
  </div>
</template>

